begin;
select plan(11);
insert into auth.users(id) values('30000000-0000-0000-0000-000000000001');
select lives_ok($$select public.submit_contribution('30000000-0000-0000-0000-000000000001','{"kind":"report","title":"Prova invio","description":"Descrizione prova invio","zone":"Milano","category":"altro","latitude":45.4642,"longitude":9.1899,"event_at":"2026-10-19T12:00:00Z","testimony":"direct","editorial_status":"approved","fact_status":"corroborated"}')$$,'Backend accepts valid report');
select is((select editorial_status::text from public.contributions limit 1),'published','Report is public but client cannot set editorial approval');
select is((select fact_status::text from public.contributions limit 1),'unverified','Client cannot set verified status');
select is((select latitude::numeric from public.contributions limit 1),45.46::numeric,'Precise locations are rounded');
select throws_ok($$select public.submit_contribution('30000000-0000-0000-0000-000000000001','{"kind":"news"}')$$,'P0001','Solo moderatori','Users cannot create editorial news');
set local role anon;
select is((select count(*)::integer from public.contributions),1,'Automatically published report is public');
reset role;
select lives_ok($$select public.submit_contribution('30000000-0000-0000-0000-000000000001','{"kind":"post","title":"Prova bacheca","description":"Descrizione prova bacheca","zone":"Milano","category":"altro","event_at":"2026-10-19T12:00:00Z","testimony":"direct","editorial_status":"published"}')$$,'Post submission accepted');
select is((select editorial_status::text from public.contributions where kind='post'),'pending','Post still requires editorial review');
set local role anon;
select is((select count(*)::integer from public.contributions),1,'Pending post remains private');
reset role;
select public.consume_limit('30000000-0000-0000-0000-000000000001','contribution',5);
select public.consume_limit('30000000-0000-0000-0000-000000000001','contribution',5);
select public.consume_limit('30000000-0000-0000-0000-000000000001','contribution',5);
select throws_ok($$select public.consume_limit('30000000-0000-0000-0000-000000000001','contribution',5)$$,'P0001','Limite di invio raggiunto. Riprova nella prossima ora.','Backend enforces hourly limit');
select lives_ok(format('select public.submit_abuse(%L,%L::jsonb)','30000000-0000-0000-0000-000000000001',jsonb_build_object('contribution_id',(select id from public.contributions where kind='report'),'reason','Segnalazione abuso di prova')),'Published unreviewed report accepts abuse reports');
select * from finish();
rollback;
